const leftBadge = (ms) => (ms == null ? '' : badge(left(ms), ms < 0 ? 'danger' : ms < 864e5 ? 'warn' : ''));
const KIND = { approved: 'ok', paid: 'ok', accepted: 'info', 'partially-approved': 'warn', 'partially-paid': 'warn', pended: 'warn', 'info-requested': 'warn', denied: 'danger', rejected: 'danger', submitted: 'info', 'in-review': 'info' };
