const parseLines = (text) => String(text || '').split('\n').map((l) => l.trim()).filter(Boolean).map((l) => { const [code, mods, units, charge] = l.split(/[\s|]+/); return { code, modifiers: mods && mods !== '-' ? mods.split(',') : [], units: Number(units) || 1, ...(charge ? { charge: Number(charge) } : {}) }; });
