const meter = (label, value, max) => h('div', { style: 'margin:0.5rem 0' }, h('div', { class: 'small' }, `${label}: ${money(value)} of ${money(max)}`), h('progress', { value: Number(value) || 0, max: Number(max) || 1, 'aria-label': label, style: 'width:100%;max-width:26rem' }));

/** Coverage at check-in, for the front desk. */
export async function coverageCard(redraw) { try { return card('Coverage at check-in', ...(await coverage(redraw))); } catch (err) { return card('Coverage at check-in', h('p', { class: 'muted', testid: 'coverage-error' }, err.message)); } }
/** Booking with insurance: says when the patient has no coverage on the date. It warns; it never blocks. */
